code_examples.code:
#include <iostream>

int main() {
    int marks[5] = {70, 85, 90, 75, 88};

    std::cout << "Third mark: " << marks[2] << '\n';
    std::cout << "All marks: ";

    for (int i = 0; i < 5; ++i) {
        std::cout << marks[i] << ' ';
    }

    std::cout << '\n';
    return 0;
}

